def shifted(cells, d): return {(r+d[0],c+d[1]) for r,c in cells}
def man1(a,b): return abs(a[0]-b[0])+abs(a[1]-b[1])==1
def marker_served(m, otherP, otherM):
    return (m in otherM) or any(man1(m,p) for p in otherP)
def pairinfo(oi,oj,d, adjacent_marker=False):
    Pi,Mi=oi['P'],oi['M']; Pj=shifted(oj['P'],d); Mj=shifted(oj['M'],d)
    ci=sum(marker_served(m,Pj,Mj) for m in Mi)
    cj=sum(marker_served(m,Pi,Mi) for m in Mj)
    return ci,cj, len(Pi & Pj)
from itertools import product
paircands={}
keys=list(objs)
for ix,i in enumerate(keys):
 for j in keys[ix+1:]:
    cand=[]
    for dr in range(-14,15):
     for dc in range(-14,15):
      x=pairinfo(objs[i],objs[j],(dr,dc))
      if x[0] or x[1]: cand.append(((dr,dc),x))
    paircands[i,j]=cand
    full=[z for z in cand if z[1][0]==len(objs[i]['M']) and z[1][1]==len(objs[j]['M']) and z[1][2]==0]
    print(i,j,'cands',len(cand),'full',full[:10], 'count',len(full))

for (i,j),cand in paircands.items():
 vals=[]
 for d,x in cand:
  Pi,Mi=objs[i]['P'],objs[i]['M']; Pj=shifted(objs[j]['P'],d); Mj=shifted(objs[j]['M'],d)
  ov=len(Mi & Mj)
  adj=sum(any(man1(m,p) for p in Pj) for m in Mi)+sum(any(man1(m,p) for p in Pi) for m in Mj)
  if ov>=1 and not (Pi&Pj): vals.append((d,ov,adj,x[:2]))
 print(i,j, sorted(vals,key=lambda z:(-z[1],-z[2]))[:12])

