def detail(i,j,d):
 Pi,Mi=objs[i]['P'],objs[i]['M']; Pj=shifted(objs[j]['P'],d); Mj=shifted(objs[j]['M'],d)
 def contacts(M,OP,OM):
  out=[]
  for m in sorted(M):
   if m in OM: out.append((m,'M'))
   else:
    ps=[p for p in OP if man1(m,p)]
    out.append((m,ps))
  return out
 print(i,'markers:',contacts(Mi,Pj,Mj))
 print(j,'markers:',contacts(Mj,Pi,Mi))
 print('marker overlap',Mi&Mj, 'P overlap',Pi&Pj)
